<script setup>const email=ref(''),msg=ref('');async function submit(){await $fetch('/api/auth/forgot',{method:'POST',body:{email:email.value}});msg.value='Jika email terdaftar, tautan reset telah dibuat. Pada mode demo lihat terminal server.'}</script><template><main class="max-w-md mx-auto p-8"><form class="panel space-y-4" @submit.prevent="submit"><h1 class="text-2xl font-black">Lupa password</h1><input v-model="email" type="email" class="input" placeholder="Email" required><button class="btn-primary w-full">Kirim tautan reset</button><p>{{msg}}</p><NuxtLink to="/login">Kembali</NuxtLink></form></main></template>